"""Make Noctiluca's watch-page test card, card.webm.

Four seconds of ffmpeg's own `testsrc2` pattern (a moving gradient, a
counter and a clock), 640 x 360 at 30 frames a second, VP9 in WebM,
silent. The pattern is generated by ffmpeg, so the fixture carries no
footage of anyone's. The watch page (`../watch.html`) loops it; at 30
frames a second it is what frame pacing is measured on.

Run from anywhere: `python3 -I make_card.py` (needs an ffmpeg with
libvpx-vp9); it writes beside itself.
"""

import os
import subprocess

HERE = os.path.dirname(os.path.abspath(__file__))

subprocess.run(
    [
        "ffmpeg", "-hide_banner", "-loglevel", "error", "-y",
        "-f", "lavfi", "-i", "testsrc2=size=640x360:rate=30:duration=4",
        "-c:v", "libvpx-vp9", "-b:v", "300k", "-threads", "1", "-row-mt", "0",
        "-pix_fmt", "yuv420p", "-an", os.path.join(HERE, "card.webm"),
    ],
    check=True,
)
